export function resolveEconomyWcid(wcidOrKind) {
  if (typeof wcidOrKind === "number" && Number.isFinite(wcidOrKind)) {
    const n = Math.trunc(wcidOrKind);
    if (ECONOMY_WCID_TO_KIND[n] !== undefined) return n;
    if (ECONOMY_KIND_TO_WCID[n] !== undefined) return ECONOMY_KIND_TO_WCID[n];
    return null;
  }
  if (typeof wcidOrKind === "string") {
    const t = wcidOrKind.trim();
    if (/^\d+$/.test(t)) return resolveEconomyWcid(Number.parseInt(t, 10));
    return ECONOMY_NAME_TO_WCID[t.toLowerCase()] ?? null;
  }
  return null;
}
